import os
import tempfile
import pytest

import envcfg


def test_defaults_only():
    cfg = envcfg.load_config({"a": 1, "b": 2})
    assert cfg == {"a": 1, "b": 2}


def test_toml_only():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        f.write(b'a = 10\n')
        path = f.name
    try:
        cfg = envcfg.load_config({}, toml_path=path)
        assert cfg == {"a": 10}
    finally:
        os.unlink(path)


def test_env_only():
    env = {"APP__A": "100"}
    cfg = envcfg.load_config({}, env=env)
    assert cfg == {"a": 100}


def test_precedence_defaults_toml_env():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        f.write(b'a = 10\n')
        path = f.name
    try:
        env = {"APP__A": "20"}
        cfg = envcfg.load_config({"a": 1}, toml_path=path, env=env)
        assert cfg == {"a": 20}
    finally:
        os.unlink(path)


def test_nested_defaults():
    cfg = envcfg.load_config({"server": {"port": 8080, "host": "localhost"}})
    assert cfg == {"server": {"port": 8080, "host": "localhost"}}


